const settingsIcon=uiDocument.createElement('button');settingsIcon.type='button';settingsIcon.className='app-icon';settingsIcon.setAttribute('aria-label','设置');settingsIcon.innerHTML='<span class="icon-box jp-settings-icon"><svg viewBox="0 0 32 32" shape-rendering="crispEdges" aria-hidden="true"><path fill="#674b60" d="M12 1h8v5h5v5h5v10h-5v5h-5v5h-8v-5H7v-5H2V11h5V6h5z"/><path fill="#bd8f9e" d="M13 3h6v5h6v5h3v6h-5v6h-4v4h-6v-5H8v-5H4v-6h5V8h4z"/><path fill="#f7d5d8" d="M13 5h4v6h7v4h-5v8h-4v-5H9v-5h4z"/><path fill="#674b60" d="M12 11h9v11h-9z"/><path fill="#fff5ce" d="M14 13h5v6h-5z"/></svg></span><small>设置</small>';$('.apps').append(settingsIcon);settingsIcon.onclick=()=>bridge.openSettings();
