extra.textContent+='.jp-collapse{position:absolute;top:5px;right:22px;z-index:1000;width:25px;height:22px;border-radius:10px;background:#f3c5d7;color:#684052;pointer-events:auto}.speaker{z-index:999;pointer-events:auto;cursor:grab;touch-action:none}.device{touch-action:auto}.chat-composer{flex-wrap:wrap}.chat-composer .jp-real-send{width:auto;flex:0 0 auto;font-size:11px;padding:7px}.jp-delivery{display:block;text-align:right;font-size:9px;opacity:.65}';
const originalSync=sync;
cropDays=function(crop){const row=[...$$('.sale-row[data-kind="seed"]')].find(r=>r.dataset.name.replace(/种子$/,'')===crop);const days=Number(row?.dataset.days);return Number.isFinite(days)&&days>0?days:'';};
sync=function(){originalSync();if(liveState){$('#bagCapacity').textContent=liveState.inventory.length+' / '+liveState.capacity+' 格';}if(!applying)bridge.draftChanged?.(captureDraft());};
function capturePlots(){return [...$$('#field .soil')].map(s=>({crop:s.dataset.crop||'',days:s.dataset.days===''?null:Number(s.dataset.days),wet:s.classList.contains('wet'),fertilizer:s.dataset.fertilizer||''}));}
function captureDraft(){return {actions:[...actions],plots:capturePlots()};}
const initial={gold:0,capacity:24,calendar:{season:'未确认',day:0,year:0,time:'--:--',weather:'未确认',weekday:''},inventory:[],plots:Array.from({length:24},()=>({crop:'',days:null,wet:false,fertilizer:''})),relationships:Object.fromEntries(chatRoles.map(r=>[r.id,0])),locations:{},quests:[],animals:[],buildings:[],calendarEvents:[],notes:''};
function drawPlots(plots){$('#field').replaceChildren();plots.forEach(p=>{makeSoil(p.crop,p.wet,false,p.days);const s=$$('#field .soil')[$$('#field .soil').length-1];s.dataset.fertilizer=p.fertilizer||'';s.dataset.originalFertilizer=p.fertilizer||'';s.dataset.days=p.days==null?'':String(p.days);if(p.stage&&p.stage!=='mature'&&s.dataset.days==='0')s.dataset.days='';s.dataset.originalDays=s.dataset.days;renderSoil(s);});updateFieldInfo();}
function drawInventory(){
  $('#bagList').innerHTML=liveState.inventory.map(r=>'<div class="row sale-row" data-name="'+esc(r.name)+'" data-count="'+r.count+'" data-price="'+(r.price||0)+'" data-price-unknown="'+(r.priceUnknown?'1':'0')+'" data-kind="'+(r.kind||'item')+'" data-days="'+(r.days||0)+'" data-qty="1"><div class="main"><span class="bag-select"></span><div><h3>'+esc(r.name)+' <span class="item-count">×'+r.count+'</span></h3><div class="sub">'+(r.kind==='seed'?(r.days||'?')+' 天成熟 · ':'')+(r.priceUnknown?'价格未知':(r.price||0)+'g / 个')+'</div></div><div class="item-tools"><button class="qty-step" data-d="-1">−</button><span class="qty-num">1</span><button class="qty-step" data-d="1">＋</button><button class="btn sell-one">出售</button></div></div></div>').join('');
  $$('.qty-step').forEach(b=>b.onclick=()=>{const r=b.closest('.sale-row');const q=Math.max(1,Math.min(+r.dataset.count,+r.dataset.qty+ +b.dataset.d));r.dataset.qty=q;r.querySelector('.qty-num').textContent=q;});
  $$('.sell-one').forEach(b=>b.onclick=()=>{const r=b.closest('.sale-row');if(+r.dataset.count===0)return toast('物品数量为零');if(r.dataset.priceUnknown==='1')return toast('售价未知，请先确认价格');const a='出售'+r.dataset.name+'×'+r.dataset.qty+'（'+(+r.dataset.qty*+r.dataset.price)+'g）';if(r.dataset.saleAction){removeExactAction(r.dataset.saleAction);r.dataset.saleAction='';}else{actions.push(a);r.dataset.saleAction=a;}sync();});
  $$('.sale-row').forEach(r=>r.onclick=e=>{if(selecting&&!e.target.closest('button'))r.classList.toggle('batch-on');});
}
rebuildFieldState=function(){if(!liveState)return;drawPlots(liveState.plots);for(const a of actions){let m=a.match(/第(\d+)格/);if(!m)continue;const i=+m[1]-1;if(a.startsWith('扩充')){if(!$$('#field .soil')[i])makeSoil();continue;}const s=$$('#field .soil')[i];if(!s)continue;if(a.includes('播种')){s.dataset.crop=a.split('播种')[1];s.dataset.days=cropDays(s.dataset.crop);}if(a.includes('浇水'))s.classList.add('wet');if(a.includes('施用'))s.dataset.fertilizer=a.split('施用')[1];if(a.startsWith('收获')||a.startsWith('铲除')){s.dataset.crop='';s.dataset.days='';}renderSoil(s);}updateFieldInfo();};
$('#bagUpgrade').onclick=()=>{const capacity=liveState.capacity+12;if(actions.some(a=>a.startsWith('扩充背包')))return toast('本轮已安排扩充');if(finance().balance<2000)return toast('金币不足 2000g');toggle('扩充背包至'+capacity+'格（支出2000g）');};
normalizeBagUpgrades=function(){};
function messageMarkup(m){if(['gift','redpacket'].includes(m.type))return '<button class="jp-transfer-card '+(m.type==='redpacket'?'jp-redpacket':'')+'" data-transfer="'+esc(m.id)+'" '+(m.from==='me'||m.claimed?'disabled':'')+'><span>'+(m.type==='gift'?'♧':'♡')+'</span><b>'+(m.type==='gift'?esc(m.item)+' ×'+m.count:m.amount+' 金币')+'</b><small>'+esc(m.note||'一点小心意')+'</small><em>'+(m.from==='me'?'已送出':m.claimed?'已领取':'点击领取')+'</em></button>';if(m.type==='image'){const item=bridge.getImage(m.mediaId);return item?'<figure class="jp-photo-bubble"><img loading="lazy" referrerpolicy="no-referrer" src="'+esc(item.dataUrl)+'" alt="'+esc(item.description||'用户发送的图片')+'">'+(item.description?'<figcaption>'+esc(item.description)+'</figcaption>':'')+'</figure>':esc(m.text+'（图片仅在导入的浏览器保存）');}if(m.type==='sticker'){const item=bridge.getSticker(m.stickerId);return item?'<figure class="jp-sticker-bubble"><img src="'+esc(item.dataUrl)+'" alt="'+esc(item.name)+'"><figcaption>'+esc(item.name)+'</figcaption></figure>':esc(m.text+'（图片仅在导入的浏览器保存）');}if(m.type!=='voice')return esc(m.text);const duration=m.duration||Math.max(1,Math.ceil(m.text.length/4));return '<button class="jp-voice" aria-label="模拟语音，点击展开或收起文字"><span class="jp-wave">▂ ▅ ▃ ▇ ▄ ▆ ▂</span><b>'+duration+'″</b><small>转文字</small></button><div class="jp-transcript">'+esc(m.text)+'</div>';}
renderChatRoom=function(role){if(activeRole?.id!==role.id){stickerPanel.hidden=true;stickerButton.setAttribute('aria-expanded','false');}activeRole=role;roomSettings.hidden=!!role.members;unread[role.id]=false;bridge.read?.(role.id);const body=$('#chatRoom .chat-room-body');$('#chatRoomName').textContent=role.name;const messages=histories[role.id]||[];body.classList.add('has-messages');body.innerHTML=messages.length?messages.map(m=>{const speaker=chatRoles.find(r=>r.id===m.speakerId)||role;return '<div class="chat-message '+(m.from==='me'?'outgoing':'incoming')+'">'+(m.from==='me'?'<span class="chat-avatar">'+userPortrait(role.id)+'</span>':'<span class="chat-avatar">'+threadPortrait(speaker)+'</span>')+'<div class="chat-message-content">'+(role.members&&m.from!=='me'?'<small class="jp-speaker">'+esc(speaker.name)+'</small>':'')+'<div class="chat-bubble">'+messageMarkup(m)+'</div><span class="chat-message-time">'+esc(m.time||'')+(m.from==='me'?' · '+({queued:'✓',sending:'···',failed:'!',sent:'✓✓'}[m.status]||'✓✓'):'')+'</span></div></div>';}).join(''):'<div class="jp-live-note">写下第一条消息，和'+esc(role.name)+'聊天吧。</div>';if(typingStates[role.id]){const tip=uiDocument.createElement('div');tip.className='jp-typing';tip.setAttribute('role','status');tip.innerHTML='<span>'+esc(typingStates[role.id])+'</span><i></i><i></i><i></i>';body.append(tip);}body.querySelectorAll('.jp-voice').forEach(b=>b.onclick=()=>{b.classList.add('playing');setTimeout(()=>b.classList.remove('playing'),1200);const transcript=b.nextElementSibling;transcript.hidden=!transcript.hidden;});body.querySelectorAll('[data-transfer]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await bridge.claimTransfer(b.dataset.transfer);}catch(e){toast(e.message);b.disabled=false;}});body.scrollTop=body.scrollHeight;};
renderChatThreads=function(){const query=$('#chatSearch').value.trim();$('#chatThreads').innerHTML=threadRoles.filter(r=>(r.name+r.job).includes(query)).map(r=>{const last=histories[r.id]?.at(-1);return '<button class="chat-thread" data-role="'+r.id+'"><span class="chat-avatar">'+threadPortrait(r)+'</span><span class="chat-thread-main"><span class="chat-thread-name">'+r.name+(unread[r.id]?' ●':'')+'<em>'+r.job+'</em></span><span class="chat-thread-preview">'+esc(typingStates[r.id]||(last?.type==='voice'?'[语音] ':'' )+(last?.text?.slice(0,42)||'尚无消息'))+'</span></span><span class="chat-thread-end">›</span></button>';}).join('');$$('#chatThreads .chat-thread').forEach(b=>b.onclick=()=>{renderChatRoom(threadRoles.find(r=>r.id===b.dataset.role));showChatHelp();$('#chatListView').hidden=true;$('#chatRoom').hidden=false;$('#chatApp').classList.add('chat-room-open');});};
// Replace the previously captured search callback.
$('#chatSearch').addEventListener('input',()=>queueMicrotask(renderChatThreads));

const groupRoles=[{id:'group-all',name:'月亮谷邻里群',job:'全员群聊',members:chatRoles.map(r=>r.id)},{id:'group-twins',name:'莱恩 · 莱尔 · 我',job:'三人群聊',members:['11','10']}];
const threadRoles=[...groupRoles,...chatRoles];
function threadPortrait(role){return role.members?'<span class="jp-group-avatar">♧</span>':avatarMarkup(role.id,'role',portraitMarkup(role));}
function showChatHelp(){if(localStorage.getItem('junimo_pocket_chat_help_v9'))return;const dialog=uiDocument.createElement('div');dialog.className='jp-review';dialog.innerHTML='<div class="jp-review-card"><h3>像手机一样聊天</h3><p>➤：先发一个气泡，不触发回复。可以连续发好几条。</p><p>右侧对话气泡按钮：把当前输入一起发出，让对方回复前面累积的消息。</p><p>私聊只有选中的角色；群聊会在每条消息上显示发言人。</p><button>知道了</button></div>';$('.screen').append(dialog);dialog.querySelector('button').onclick=()=>{localStorage.setItem('junimo_pocket_chat_help_v9','1');dialog.remove();};}
const composer=$('.chat-composer input'),sendButton=$('.chat-composer button');composer.disabled=false;sendButton.disabled=false;sendButton.textContent='➤';sendButton.title='虚拟发送：只发气泡' ;sendButton.setAttribute('aria-label','虚拟发送');
const realSend=uiDocument.createElement('button');realSend.className='jp-real-send';realSend.innerHTML='<svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11a8 8 0 0 1-8 8H5l-3 3V11a9 9 0 0 1 18 0Z"/><path d="M7 11h.01M11 11h.01M15 11h.01" stroke-width="2.8"/></svg>';realSend.title='真正发送：触发回复';realSend.setAttribute('aria-label','真正发送');$('.chat-composer').append(realSend);
const voiceButton=uiDocument.createElement('button');voiceButton.className='jp-voice-compose';voiceButton.setAttribute('aria-label','发送模拟语音');voiceButton.title='模拟语音（文字输入）';voiceButton.innerHTML='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="8" y="2" width="8" height="13" rx="4"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg>';$('.chat-composer').insertBefore(voiceButton,composer);
voiceButton.onclick=()=>{if(!activeRole)return;const role=activeRole,dialog=uiDocument.createElement('div');dialog.className='jp-review jp-voice-dialog';dialog.innerHTML='<div class="jp-review-card"><h3>语音消息</h3><div class="jp-voice-visual" aria-hidden="true">'+Array.from({length:19},()=>'<i></i>').join('')+'</div><p>输入想说的话，发出后显示语音气泡与转文字，不使用麦克风。</p><textarea aria-label="模拟语音内容" placeholder="想对TA说什么…"></textarea><div><button class="jp-voice-cancel">取消</button><button class="jp-voice-queue" title="先发气泡">存为气泡</button><button class="jp-voice-send" title="发送并触发回复">发送语音</button></div><p class="jp-review-error"></p></div>';$('.screen').append(dialog);dialog.querySelector('.jp-voice-cancel').onclick=()=>dialog.remove();async function submit(real){const input=dialog.querySelector('textarea'),text=input.value.trim();if(!text)return;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{await bridge.queueBubble(role,{type:'voice',text});dialog.remove();if(real)await bridge.send(role);}catch(e){if(dialog.isConnected){dialog.querySelector('.jp-review-error').textContent=e.message;dialog.querySelectorAll('button').forEach(b=>b.disabled=false);}else toast(e.message);}}dialog.querySelector('.jp-voice-queue').onclick=()=>submit(false);dialog.querySelector('.jp-voice-send').onclick=()=>submit(true);};
const tools=uiDocument.createElement('div');tools.className='jp-chat-tools';$('.chat-composer').after(tools);tools.append(voiceButton);
const stickerButton=uiDocument.createElement('button');stickerButton.className='jp-sticker-tool';stickerButton.setAttribute('aria-label','表情包');stickerButton.title='表情包';stickerButton.innerHTML='<svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M8 14q4 5 8 0M8 8v3M16 8v3"/></svg>';tools.append(stickerButton);realSend.title='让对方回复';
const imageButton=uiDocument.createElement('button');imageButton.className='jp-image-tool';imageButton.setAttribute('aria-label','发送图片');imageButton.title='照片 / 截图';imageButton.innerHTML='<svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/></svg>';tools.insertBefore(imageButton,stickerButton);
const stickerPanel=uiDocument.createElement('div');stickerPanel.className='jp-sticker-panel';stickerPanel.hidden=true;stickerPanel.innerHTML='<div class="jp-sticker-heading"><span>我的表情包</span><button aria-label="收起表情包">⌄</button></div><div class="jp-sticker-grid"></div><p class="jp-review-error" role="status"></p>';tools.after(stickerPanel);stickerPanel.querySelector('button').onclick=()=>{stickerPanel.hidden=true;stickerButton.setAttribute('aria-expanded','false');};
function drawStickerPanel(){const grid=stickerPanel.querySelector('.jp-sticker-grid');grid.replaceChildren();for(const item of bridge.stickerCatalog()){const full=bridge.getSticker(item.id),b=uiDocument.createElement('button');b.className='jp-sticker-choice';b.setAttribute('aria-label','发送表情包 '+item.name);b.innerHTML='<img loading="lazy" referrerpolicy="no-referrer" src="'+esc(full.dataUrl)+'" alt=""><span>'+esc(item.name)+'</span>';b.onclick=async()=>{const role=activeRole;if(!role)return;b.disabled=true;try{await bridge.queueBubble(role,{type:'sticker',stickerId:item.id});stickerPanel.querySelector('.jp-review-error').textContent='';}catch(e){stickerPanel.querySelector('.jp-review-error').textContent=e.message;}finally{b.disabled=false;}};grid.append(b);}const add=uiDocument.createElement('button');add.className='jp-sticker-choice jp-add-sticker';add.setAttribute('aria-label','添加表情包');add.innerHTML='<b>＋</b><span>添加</span>';add.onclick=()=>openImageImport('sticker');grid.append(add);}
stickerButton.setAttribute('aria-expanded','false');stickerButton.onclick=()=>{if(!activeRole)return;stickerPanel.hidden=!stickerPanel.hidden;stickerButton.setAttribute('aria-expanded',String(!stickerPanel.hidden));if(!stickerPanel.hidden)drawStickerPanel();};imageButton.onclick=()=>openImageImport('image');
function openImageImport(kind){if(!activeRole)return;const role=activeRole,isSticker=kind==='sticker',dialog=uiDocument.createElement('div');dialog.className='jp-review jp-media-import';dialog.innerHTML='<div class="jp-review-card jp-sticker-import"><div class="jp-sticker-heading"><h3>'+(isSticker?'添加表情包':'发送图片')+'</h3><button aria-label="关闭图片窗口">×</button></div><p>'+(isSticker?'取个名字，AI 就能理解这张表情表达的心情。':'照片、截图都可以；写点说明告诉对方图片内容。')+'</p><label>本地上传<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" aria-label="'+(isSticker?'表情包图片':'聊天图片')+'"></label><label>或使用图床链接<input type="url" aria-label="图床图片链接" placeholder="https://… 图片直链"></label><small>本地图片保存在当前浏览器；图床链接需可直接打开图片。</small><img class="jp-sticker-preview" referrerpolicy="no-referrer" hidden>'+(isSticker?'<label>表情包名称<input maxlength="40" aria-label="表情包名称" placeholder="例如：猫猫点头"></label>':'')+'<label>'+(isSticker?'表情包说明':'图片说明')+'<textarea maxlength="'+(isSticker?'300':'1000')+'" aria-label="'+(isSticker?'表情包说明':'图片说明')+'" placeholder="'+(isSticker?'画面、情绪或适合什么场合':'例如：这是我刚播种后的农田照片')+'"></textarea></label><div><button class="jp-sticker-describe">AI 识图填写说明</button><button class="jp-sticker-save">'+(isSticker?'保存表情包':'发送图片气泡')+'</button></div><p class="jp-review-error" role="status"></p></div>';$('.screen').append(dialog);dialog.querySelector('[aria-label="关闭图片窗口"]').onclick=()=>dialog.remove();const file=dialog.querySelector('input[type=file]'),url=dialog.querySelector('input[type=url]'),preview=dialog.querySelector('img'),error=dialog.querySelector('.jp-review-error');let source='',loading=false,revision=0;
function show(sourceValue){source=sourceValue;preview.src=source;preview.hidden=false;error.textContent='';}
file.onchange=async()=>{const revisionId=++revision;loading=true;source='';url.value='';try{const value=await bridge.prepareSticker(file.files[0]);if(revisionId===revision)show(value);}catch(e){if(revisionId===revision)error.textContent=e.message;}finally{if(revisionId===revision)loading=false;}};
url.oninput=()=>{revision++;loading=false;source='';preview.hidden=true;file.value='';if(!url.value.trim())return;try{show(bridge.validateImageSource(url.value));}catch(e){error.textContent=e.message;}};
preview.onerror=()=>{error.textContent='图片未能预览，请检查直链是否允许外部访问';};
dialog.querySelector('.jp-sticker-describe').onclick=async e=>{if(!source||loading){error.textContent='请先选择图片或填写直链';return;}const b=e.currentTarget;b.disabled=true;try{dialog.querySelector('textarea').value=await bridge.describeSticker(source,kind);}catch(err){error.textContent=err.message;}finally{b.disabled=false;}};
dialog.querySelector('.jp-sticker-save').onclick=async e=>{if(!source||loading){error.textContent='请先选择图片并等待读取完成';return;}const b=e.currentTarget;b.disabled=true;try{const description=dialog.querySelector('textarea').value;if(isSticker){await bridge.saveSticker({name:dialog.querySelector('[aria-label="表情包名称"]').value,description,dataUrl:source});drawStickerPanel();stickerPanel.hidden=false;stickerButton.setAttribute('aria-expanded','true');}else{const item=await bridge.saveImage({description,dataUrl:source});await bridge.queueBubble(role,{type:'image',mediaId:item.id});}dialog.remove();}catch(err){error.textContent=err.message;b.disabled=false;}};}

