function openTransfer(kind){if(!activeRole)return;const role=activeRole,state=bridge.getSocialState(),gift=kind==='gift',dialog=uiDocument.createElement('div');dialog.className='jp-review jp-transfer-compose';const members=role.members?chatRoles.filter(r=>role.members.includes(r.id)):[role];dialog.innerHTML='<div class="jp-review-card"><h3>'+(gift?'从背包送礼':'发一个金币红包')+'</h3><p>发送后立即结算并记入行动篮，再点对话按钮让对方回复。</p><label>送给<select aria-label="收礼人">'+members.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('')+'</select></label>'+(gift?'<label>背包物品<select aria-label="赠送物品">'+state.inventory.filter(x=>x.count>0).map(x=>'<option value="'+esc(x.name)+'">'+esc(x.name)+' · 剩余 '+x.count+'</option>').join('')+'</select></label><label>数量<input type="number" min="1" step="1" value="1" aria-label="礼物数量"></label>':'<p>可用余额：'+state.gold+' 金币</p><label>红包金额<input type="number" min="1" step="1" value="1" max="'+state.gold+'" aria-label="红包金额"></label>')+'<label>留句话<input maxlength="100" aria-label="赠送留言" placeholder="一点小心意"></label><p class="jp-review-error"></p><button class="jp-cancel">取消</button><button class="jp-confirm">'+(gift?'确认赠送':'发送红包')+'</button></div>';$('.screen').append(dialog);dialog.querySelector('.jp-cancel').onclick=()=>dialog.remove();dialog.querySelector('.jp-confirm').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await bridge.sendTransfer(role,{kind,recipientId:dialog.querySelector('[aria-label="收礼人"]').value,item:dialog.querySelector('[aria-label="赠送物品"]')?.value,count:+dialog.querySelector('[aria-label="礼物数量"]')?.value,amount:+dialog.querySelector('[aria-label="红包金额"]')?.value,note:dialog.querySelector('[aria-label="赠送留言"]').value});dialog.remove();}catch(err){dialog.querySelector('.jp-review-error').textContent=err.message;b.disabled=false;}};}
