const mailApp=uiDocument.createElement('section');mailApp.id='jpMailApp';mailApp.className='app';mailApp.innerHTML='<header class="app-head"><button class="back" aria-label="邮件返回桌面">‹</button><b>邮件</b><button class="jp-mail-check" aria-label="重新生成信件" title="根据正文与手机聊天生成1–4封新信，保留已有信件"><span class="jp-mail-refresh">↻</span><span>重新生成</span></button></header><div class="app-body"><div class="jp-mail-intro"><small>MOON VALLEY POST</small><h3>寄给你的日常</h3><p>邀请、委托，还有未说出口的话</p></div><p class="jp-mail-progress" role="status" hidden>正在翻阅正文与聊天，写信中…</p><div class="jp-mail-list"></div></div>';$('.screen').append(mailApp);mailApp.querySelector('.back').onclick=goHome;mailIcon.onclick=()=>{goHome();$('#home').style.display='none';$('#screen').classList.add('app-open');mailApp.classList.add('active');drawMail();};mailApp.querySelector('.jp-mail-check').onclick=async e=>{const b=e.currentTarget;const progress=mailApp.querySelector('.jp-mail-progress');b.disabled=true;b.classList.add('loading');progress.hidden=false;progress.textContent='正在翻阅正文与聊天，写信中…';try{await bridge.collectMail();progress.textContent='新信已放进信箱';}catch(err){progress.textContent=err.message;toast(err.message);}finally{b.disabled=false;b.classList.remove('loading');}};
function senderName(l){return l.anonymous?'匿名来信':l.senderId==='stranger'?(l.senderName||'陌生来信'):chatRoles.find(r=>r.id===l.senderId)?.name||'月亮谷邮局';}
function drawMail(){const list=mailApp.querySelector('.jp-mail-list');list.innerHTML=mailLetters.length?mailLetters.map(l=>'<button class="jp-mail-row" data-mail="'+esc(l.id)+'"><span class="jp-mail-seal">'+({letter:'✉',love:'♡',invitation:'♧',commission:'▤'}[l.kind]||'✉')+'</span><span><b>'+esc(l.subject)+(l.read?'':' · 新')+'</b><small>'+esc(senderName(l))+' · '+esc(l.time||'')+'</small></span><i>›</i></button>').join(''):'<p class="jp-mail-empty">信箱还是空的<br>故事推进时可能收到来信，也可以点右上角重新生成 1–4 封新信</p>';list.querySelectorAll('[data-mail]').forEach(b=>b.onclick=()=>openLetter(b.dataset.mail));mailIcon.querySelector('small').textContent='邮件'+(mailLetters.some(l=>!l.read)?' ●':'');}
function openLetter(id){const letter=mailLetters.find(l=>l.id===id);if(!letter)return;letter.read=true;bridge.readMail(id).catch(e=>toast(e.message));drawMail();const quest=mailQuests.find(q=>q.id===id),dialog=uiDocument.createElement('div');dialog.className='jp-review jp-letter';dialog.innerHTML='<article class="jp-review-card"><small>'+esc(senderName(letter))+'</small><h3>'+esc(letter.subject)+'</h3><div class="jp-letter-body">'+esc(letter.body)+'</div>'+(letter.quest?'<div class="jp-mail-commission">交付 '+esc(letter.quest.item)+' ×'+letter.quest.count+'<br>报酬 '+letter.quest.rewardGold+' 金币<br><small>'+(quest?.status==='completed'?'已完成':quest?'已接取，可在任务栏交付':'接取后加入任务栏')+'</small></div>':'')+'<p class="jp-review-error"></p><button class="jp-letter-close">收好信件</button>'+(letter.quest&&!quest?'<button class="jp-letter-accept">接取委托</button>':'')+'</article>';$('.screen').append(dialog);dialog.querySelector('.jp-letter-close').onclick=()=>dialog.remove();const accept=dialog.querySelector('.jp-letter-accept');if(accept)accept.onclick=async()=>{accept.disabled=true;try{await bridge.acceptMail(id);dialog.remove();toast('已加入任务栏与行动篮');}catch(e){dialog.querySelector('.jp-review-error').textContent=e.message;accept.disabled=false;}};}
