 $('#quest .app-head span').textContent=state.quests.length+' 项';$('#quest .app-body .list').innerHTML=state.quests.map((q,i)=>'<div class="row quest" data-q="'+i+'"><div class="main"><div><h3>'+esc(q.name)+'</h3><div class="sub">'+esc(q.status)+'</div>'+(Number.isFinite(q.progress)?'<div class="progress"><i style="width:'+Math.max(0,Math.min(100,q.progress))+'%"></i></div>':'')+'</div><span class="tag pink">'+esc(q.deadline||'查看详情')+'</span></div></div>').join('')||'<p class="tip">尚无任务。</p>';
