function reviewState(text,summary,onConfirm){const dialog=uiDocument.createElement('div');dialog.className='jp-review';dialog.innerHTML='<div class="jp-review-card"><h3>核对变量修改</h3><p class="jp-review-summary"></p><textarea aria-label="待确认的文字变量"></textarea><p class="jp-review-error" role="status"></p><div><button class="jp-review-cancel">取消</button><button class="jp-review-confirm">确认应用</button></div></div>';dialog.querySelector('.jp-review-summary').textContent=summary;dialog.querySelector('textarea').value=text;dialog.querySelector('.jp-review-cancel').onclick=()=>dialog.remove();dialog.querySelector('.jp-review-confirm').onclick=async()=>{const b=dialog.querySelector('.jp-review-confirm');b.disabled=true;try{await onConfirm(dialog.querySelector('textarea').value);dialog.remove();}catch(e){dialog.querySelector('.jp-review-error').textContent=e.message;}finally{b.disabled=false;}};$('.screen').append(dialog);}
